#include "agent/agent-runtime.h"
#include "plan/plan-in-memory.h"
#include <cassert>

class planner final : public common_planner { public: common_plan_proposal create_plan(const common_agent_request & request, std::string & error) override { error.clear(); common_plan_proposal p; p.plan.id = "turn-1"; p.plan.session_id = request.session_id; p.plan.goal = request.prompt; p.plan.success_criteria = "answer"; common_plan_step step; step.id = "lookup"; step.title = "Lookup"; step.objective = "Get facts"; step.status = common_plan_step_status::active; step.selected_tool = "lookup"; step.tool_call = common_plan_tool_call{"lookup", R"({"id":"status"})"}; p.plan.steps.push_back(std::move(step)); p.plan.active_step_id = "lookup"; p.plan.status = common_plan_status::active; return p; } };
class executor final : public common_action_executor { public: std::string generate_draft(const common_agent_request &, const common_plan_state &, const std::vector<std::string> &, std::string & error) override { error.clear(); return "draft"; } };
class reflector final : public common_reflection_engine { public: common_reflection_result evaluate(const common_agent_request &, const common_plan_state &, const std::string &, std::string & error) override { error.clear(); common_reflection_result r; r.decision = common_reflection_decision::accept; r.ready_to_answer = true; return r; } };
int main() { common_plan_in_memory_store store; std::string error; assert(store.open("", error)); common_tool_registry tools; common_registered_tool tool; tool.name = "lookup"; tool.arguments_schema = R"({"type":"object","additionalProperties":false,"required":["id"],"properties":{"id":{"type":"string"}}})"; tool.handler = [](const std::string &, std::string & value, std::string & err) { value = "current status"; err.clear(); return true; }; assert(tools.register_tool(std::move(tool), error)); planner p; executor e; reflector r; common_agent_runtime runtime(store, p, e, r, &tools); common_agent_request request; request.prompt = "answer"; request.session_id = "s"; request.plan_scope = common_plan_scope::global; auto result = runtime.run(request); assert(result.error.empty()); assert(result.response == "draft"); assert(result.plan_id && *result.plan_id == "turn-1"); assert(result.reflected); assert(result.events.size() == 4 && result.events[1].type == common_agent_event_type::tool_executed); auto plan = store.get("turn-1", error); assert(plan && plan->scope == common_plan_scope::global && plan->observations.size() == 1 && plan->observations[0].summary == "current status"); return 0; }
